def comb_sort(nums):
    if len(nums) <= 1:
        return nums

    gap = len(nums)
    shrink_factor = 1.3
    sorted = False

    while not sorted:
        gap = max(1, int(gap / shrink_factor))
        sorted = True

        for i in range(len(nums) - gap):
            if nums[i] > nums[i + gap]:
                nums[i], nums[i + gap] = nums[i + gap], nums[i]
                sorted = False

    return nums
```

```python
def comb_sort(nums):
    if len(nums) <= 1:
        return nums.copy()

    gap = len(nums)
    shrink_factor = 1.3
    sorted_list = nums.copy()

    while gap > 1:
        gap = max(1, int(gap / shrink_factor))
        i = 0
        while i + gap < len(sorted_list):
            if sorted_list[i] > sorted_list[i + gap]:
                sorted_list[i], sorted_list[i + gap] = sorted_list[i + gap], sorted_list[i]
            i += 1

    return sorted_list
```

