def is_samepatterns(colors, patterns):
    """
    Check if the colors list follows the same sequence of patterns as given in the patterns list.

    Args:
        colors: List of color strings.
        patterns: List of pattern strings to compare against.

    Returns:
        bool: True if the patterns of colors match the given patterns, False otherwise.
    """
    if len(colors) != len(patterns):
        return False

    def get_pattern(color):
        """Helper function to extract the pattern from a color string."""
        pattern = []
        prev_char = None
        count = 1

        for char in color:
            if char == prev_char:
                count += 1
            else:
                if prev_char is not None:
                    pattern.append(f"{prev_char}{count}")
                prev_char = char
                count = 1
        if prev_char is not None:
            pattern.append(f"{prev_char}{count}")

        return ''.join(pattern)

    color_patterns = [get_pattern(color) for color in colors]

    return all(p1 == p2 for p1, p2 in zip(patterns, color_patterns))
```

