def even_binomial_Coeff_Sum(n):
    if n == 0:
        return 1

    def binomial_coefficient(n, k):
        res = 1
        if k > n - k:
            k = n - k
        for i in range(1, k+1):
            res = res * (n - k + i) // i
        return res

    total = 0
    for k in range(0, n + 1, 2):
        total += binomial_coefficient(n, k)

    return total
```

